try:
    from pkg_resources import resource_filename
except Exception:
    try:
        # Python 3.7+ fallback using importlib.resources
        import importlib.resources as _importlib_resources
        import importlib as _importlib

        def resource_filename(package_or_requirement, resource_name):
            pkg_name = package_or_requirement if isinstance(package_or_requirement, str) else getattr(package_or_requirement, '__name__', str(package_or_requirement))
            pkg = _importlib.import_module(pkg_name)
            try:
                with _importlib_resources.as_file(_importlib_resources.files(pkg).joinpath(resource_name)) as p:
                    return str(p)
            except Exception:
                import os
                return os.path.join(os.path.dirname(pkg.__file__), resource_name)
    except Exception:
        # Last-resort conservative fallback
        import importlib as _importlib, os as _os

        def resource_filename(package_or_requirement, resource_name):
            pkg_name = package_or_requirement if isinstance(package_or_requirement, str) else getattr(package_or_requirement, '__name__', str(package_or_requirement))
            pkg = _importlib.import_module(pkg_name)
            return _os.path.join(_os.path.dirname(pkg.__file__), resource_name)


